import{_ as t,o as r,c as a,a5 as i}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Life Practice Toolkit","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/life-practice-toolkit.en.md","filePath":"public/downloads/worksheets/life-practice-toolkit.en.md","lastUpdated":1795488252000}'),o={name:"public/downloads/worksheets/life-practice-toolkit.en.md"};function n(s,e,l,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="life-practice-toolkit" tabindex="-1">Life Practice Toolkit <a class="header-anchor" href="#life-practice-toolkit" aria-label="Permalink to &quot;Life Practice Toolkit&quot;">​</a></h1><p>This is not a perfect daily streak. It is a private record for seeing reality again. When you face an important choice, scattered attention, relationship conflict, prolonged exhaustion, or care work that needs sharing, copy the relevant section and write facts and a next step.</p><p>Keep the file in a private notes or project directory. Do not include passwords, identity numbers, precise addresses, medical privacy, customer records, or unauthorised third-party information. When there is immediate danger, persistent insomnia, severe low mood, violence, debt, or legal responsibility, contact qualified professional support first.</p><h2 id="how-to-use-it" tabindex="-1">How to Use It <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to Use It&quot;">​</a></h2><ol><li>Write the date and current problem before interpreting yourself;</li><li>complete only the worksheet relevant to the current problem;</li><li>leave one executable action and one evidence location;</li><li>return on the agreed review date; do not turn the result into a personality verdict;</li><li>remove records that no longer help and keep facts that improve the next decision.</li></ol><h2 id="_1-decision-brief" tabindex="-1">1. Decision Brief <a class="header-anchor" href="#_1-decision-brief" aria-label="Permalink to &quot;1. Decision Brief&quot;">​</a></h2><h3 id="decision-brief-—-yyyy-mm-dd" tabindex="-1">Decision Brief — YYYY-MM-DD <a class="header-anchor" href="#decision-brief-—-yyyy-mm-dd" aria-label="Permalink to &quot;Decision Brief — YYYY-MM-DD&quot;">​</a></h3><p>Problem to solve:<br> Decision deadline:</p><p>Known facts and sources:<br> My interpretation:<br> Still unknown:<br> Problem type: missing information / outcome uncertainty / value conflict / identity defence<br> Non-negotiable values and boundaries:</p><p>Option A:<br> Option B:<br> Do nothing for now:</p><p>Benefits of each option:<br> Money cost of each option:<br> Health cost of each option:<br> Impact on relationships and responsibility:<br> What is reversible:</p><p>Smallest experiment:<br> Evidence gate and review date:<br> Cost gate:<br> Safety gate:<br> Responsibility gate:<br> Action when triggered: pause / stop / roll back / escalate for help<br> What evidence would overturn this choice:</p><p>Proposer:<br> Final decision owner and basis of authority:<br> Affected people and what they will actually carry:<br> Matters requiring explicit consent:<br> Implementer and required resources:<br> Reviewer and authority to pause:<br> Whose advice is relevant:<br> Current decision:<br> Review date:<br> Evidence to preserve:</p><p>Related chapter: <a href="https://byoungd.github.io/up/en/threads/part-2/decision" target="_blank" rel="noreferrer">Decision-Making: Choosing Under Uncertainty</a>. When a decision affects shared life, privacy, or unequal power, also use <a href="https://byoungd.github.io/up/en/threads/part-2/relationships" target="_blank" rel="noreferrer">Relationships</a> to check consent and exit routes.</p><h2 id="_2-attention-audit" tabindex="-1">2. Attention Audit <a class="header-anchor" href="#_2-attention-audit" aria-label="Permalink to &quot;2. Attention Audit&quot;">​</a></h2><h3 id="attention-audit-—-yyyy-mm-dd-to-yyyy-mm-dd" tabindex="-1">Attention Audit — YYYY-MM-DD to YYYY-MM-DD <a class="header-anchor" href="#attention-audit-—-yyyy-mm-dd-to-yyyy-mm-dd" aria-label="Permalink to &quot;Attention Audit — YYYY-MM-DD to YYYY-MM-DD&quot;">​</a></h3><p>Most important question this week:</p><table tabindex="0"><thead><tr><th>Area</th><th>Facts this week</th><th>Result</th><th>Adjustment next week</th></tr></thead><tbody><tr><td>Input: reading, video, meetings, chat</td><td></td><td></td><td></td></tr><tr><td>Switching: notifications, interruptions, browsing</td><td></td><td></td><td></td></tr><tr><td>Output: work, decisions, retelling, delivery</td><td></td><td></td><td></td></tr><tr><td>Relationships: conversations where I was present</td><td></td><td></td><td></td></tr><tr><td>Body: sleep, movement, energy</td><td></td><td></td><td></td></tr></tbody></table><p>One entrance to close:<br> One 25–45 minute time box to protect:<br> What I know before using AI:<br> What I can still do after closing AI:<br> One experiment for next week:</p><p>Related chapter: <a href="https://byoungd.github.io/up/en/threads/part-3/3-attention-and-judgment" target="_blank" rel="noreferrer">Attention: Return Your Attention to Yourself</a></p><h2 id="_3-relationship-conversation-card" tabindex="-1">3. Relationship Conversation Card <a class="header-anchor" href="#_3-relationship-conversation-card" aria-label="Permalink to &quot;3. Relationship Conversation Card&quot;">​</a></h2><h3 id="relationship-conversation-card-—-yyyy-mm-dd" tabindex="-1">Relationship Conversation Card — YYYY-MM-DD <a class="header-anchor" href="#relationship-conversation-card-—-yyyy-mm-dd" aria-label="Permalink to &quot;Relationship Conversation Card — YYYY-MM-DD&quot;">​</a></h3><p>Relationship and situation:<br> Who holds more resources, evaluation power, account access, information, or exit cost:<br> What I want this conversation to accomplish:<br> Can the other person safely refuse, pause, or leave this conversation?<br> Do I have explicit consent to record, upload, forward, or publish any material?</p><p>Specific facts I observed:<br> Impact and feelings:<br> What I actually need:<br> One concrete request:<br> Boundary I can enforce:<br> Which responsibilities are mine, and which are not?<br> If the conversation becomes unsafe, I will contact:</p><p>After the conversation:</p><ul><li>What did the other person actually say?</li><li>Did I really listen?</li><li>What did we explicitly agree to, and what did we not agree to?</li><li>Who owns each action, and when is it due?</li><li>What repair can be observed without requiring forgiveness or reconciliation?</li><li>What remains unresolved?</li><li>When will we review it?</li></ul><p>Related chapter: <a href="https://byoungd.github.io/up/en/threads/part-2/relationships" target="_blank" rel="noreferrer">Relationships: Becoming an Adult in Connection</a></p><h2 id="_4-recovery-reset" tabindex="-1">4. Recovery Reset <a class="header-anchor" href="#_4-recovery-reset" aria-label="Permalink to &quot;4. Recovery Reset&quot;">​</a></h2><h3 id="recovery-reset-—-yyyy-mm-dd" tabindex="-1">Recovery Reset — YYYY-MM-DD <a class="header-anchor" href="#recovery-reset-—-yyyy-mm-dd" aria-label="Permalink to &quot;Recovery Reset — YYYY-MM-DD&quot;">​</a></h3><p>Safety issue to protect today:<br> People I can contact:<br> High-risk decision to pause:<br> Today&#39;s mode: safety / reduced load / rebuilding<br> If safety worsens, what will I stop, whom will I contact, and where will I go?</p><p>Body:</p><ul><li>Sleep:</li><li>Food:</li><li>Light activity I can tolerate:</li><li>Professional support to consult:</li></ul><p>Basic-life floor: food / sleep preparation / necessary care / critical bills and communication<br> One smallest task today:<br> Evidence of completion:<br> Task limit and end time:<br> Next-day cost to check:<br> What I am allowed not to do today:<br> First action after opening the file tomorrow:</p><p>Support agreement:</p><ul><li>What a supporter may do:</li><li>What a supporter must not do in my place:</li><li>Signals that require escalation:</li><li>How accounts, documents, and decisions return as risk falls:</li><li>Minimum information needed for the safety task:</li></ul><p>Return-to-work gates:</p><ul><li>Safety gate:</li><li>Basic-life gate:</li><li>Time-boxed task gate:</li><li>Boundary communication gate:</li><li>Review date and person authorised to pause:<br> One variable to increase next:</li></ul><p>Related chapter: <a href="https://byoungd.github.io/up/en/threads/part-2/recovery" target="_blank" rel="noreferrer">Recovery: Catch Yourself Before You Push Forward</a></p><h2 id="_5-care-and-shared-responsibility-card" tabindex="-1">5. Care and Shared Responsibility Card <a class="header-anchor" href="#_5-care-and-shared-responsibility-card" aria-label="Permalink to &quot;5. Care and Shared Responsibility Card&quot;">​</a></h2><p>Choose one practical task you can discuss, such as transport, groceries, company, rest arrangements, or a bill. Ask what is needed before confirming what each person chooses to carry. This card must not score love, track someone&#39;s movements, or demand reports; keep only the minimum information both people agree to record. Family or a partner is not a required supporter. Friends, community, or professional support may help instead. Children may join age-appropriate small tasks they can refuse, but must not take responsibility for soothing adults, mediating adult conflict, or rescuing anyone.</p><h3 id="care-and-shared-responsibility-card-yyyy-mm-dd" tabindex="-1">Care and Shared Responsibility Card - YYYY-MM-DD <a class="header-anchor" href="#care-and-shared-responsibility-card-yyyy-mm-dd" aria-label="Permalink to &quot;Care and Shared Responsibility Card - YYYY-MM-DD&quot;">​</a></h3><p>Person to care for or practical task to share:<br> What the other person says they need (write &quot;unknown&quot; if not yet asked):<br> One expression of care or gratitude I want to offer:</p><p>Specific tasks I can carry myself:<br> Specific tasks where I need support:<br> Tasks that can be reduced, postponed, or stopped:<br> Time, energy, or resources I am currently willing and able to offer:<br> Time, energy, or resources the other person is willing and able to offer (&quot;unknown&quot; if unconfirmed):<br> Does the other person want to join this discussion and record?<br> How can either person refuse, pause, or adjust without blame, retaliation, or having to prove love?<br> Other people or services I can contact if this person cannot help:<br> Adult responsibilities that must stay with adults and appropriate supporters:</p><p>Next step decided together (do not fill in the other person&#39;s role without agreement):</p><ul><li>Action I choose to own and its completion date:</li><li>Action the other person explicitly agrees to own and its completion date:</li><li>What will remain unassigned or needs outside support:</li><li>Information we agree to keep, where to store it, and when to delete it:</li></ul><p>Next review date:<br> Signals to reduce the load or seek help before that date:<br> At review: is this still voluntary, is the load too heavy, and what needs to change?</p><p>Related chapter: <a href="https://byoungd.github.io/up/en/threads/part-2/care-and-carry-on" target="_blank" rel="noreferrer">Care: Finding Strength in the People We Love</a>. For boundaries, refusal, or repair, also read <a href="https://byoungd.github.io/up/en/threads/part-2/relationships" target="_blank" rel="noreferrer">Relationships</a>.</p><h2 id="_6-weekly-review" tabindex="-1">6. Weekly Review <a class="header-anchor" href="#_6-weekly-review" aria-label="Permalink to &quot;6. Weekly Review&quot;">​</a></h2><p>Answer five questions each week:</p><ol><li>Which fact changed my judgment?</li><li>Which action left an inspectable result?</li><li>Which error repeated, and what might cause it?</li><li>Which boundary needs clearer language or firmer follow-through?</li><li>Which single smallest experiment will I keep next week?</li></ol><p>Keep this toolkit beside the <a href="https://byoungd.github.io/up/en/templates/weekly-review" target="_blank" rel="noreferrer">Weekly Review template</a> in the same private directory. The purpose is not to turn life into a spreadsheet. It is to leave one small piece of fact standing when emotion becomes loud.</p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/life-practice-toolkit" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-10-04. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',53)])])}const b=t(o,[["render",n]]);export{u as __pageData,b as default};
